package org.diy.liferecorder;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import android.app.*;import android.os.Build;
/** Native pebble surfaces: vector icons, tactile controls and adaptive dialogs. */
final class PebbleSurfaces {
 static final int INK=0xff34302d,MUTED=0xff6e6863,PRIMARY=0xffb07261,SAGE=0xff46645d,SOFT=0xfff5f2ef;
 private static final java.util.Map<String,Bitmap> ICONS=new java.util.HashMap<>();
 static int dp(Context c,int value){return Math.round(value*c.getResources().getDisplayMetrics().density);}
 static GradientDrawable surface(int color,int radius,Context c){GradientDrawable b=new GradientDrawable();b.setColor(color);b.setCornerRadius(dp(c,radius));return b;}
 static Drawable states(Context c,int normal,int pressed,int disabled,int radius){StateListDrawable d=new StateListDrawable();d.addState(new int[]{-android.R.attr.state_enabled},surface(disabled,radius,c));d.addState(new int[]{android.R.attr.state_pressed},surface(pressed,radius,c));d.addState(new int[]{},surface(normal,radius,c));return new RippleDrawable(android.content.res.ColorStateList.valueOf(0x18b07261),d,surface(0xffffffff,radius,c));}
 static Drawable icon(Context c,String kind,int color){int size=dp(c,17);String key=kind+":"+color+":"+size;Bitmap bitmap=ICONS.get(key);if(bitmap==null){bitmap=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);PebbleIcon view=new PebbleIcon(c,kind,color);view.layout(0,0,size,size);view.draw(new Canvas(bitmap));ICONS.put(key,bitmap);}BitmapDrawable d=new BitmapDrawable(c.getResources(),bitmap);d.setBounds(0,0,size,size);return d;}
 static String iconFor(String label){if(label.contains("删除")||label.contains("移除"))return "trash";if(label.contains("复制"))return "copy";if(label.contains("保存")||label.contains("确认")||label.contains("采用"))return "check";if(label.contains("返回"))return "back";if(label.contains("试听")||label.contains("回听")||label.contains("播放"))return "play";if(label.contains("声纹")||label.contains("说话人"))return "person";if(label.contains("分析")||label.contains("整理")||label.contains("复盘"))return "spark";if(label.contains("设置")||label.contains("管理"))return "tune";if(label.contains("更多"))return "more";return "";}
 static void control(Button b,boolean primary){Context c=b.getContext();boolean danger=b.getText().toString().contains("删除")||b.getText().toString().contains("移除");int ink=primary?Color.WHITE:danger?0xffba1a1a:INK;int fill=primary?PRIMARY:danger?0xffffeee9:SOFT;b.setAllCaps(false);b.setTextSize(13);b.setTextColor(new android.content.res.ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{0xffa8a199,ink}));b.setBackground(states(c,fill,primary?0xff95604f:0xffebe1d8,0xfff4f0eb,24));b.setMinHeight(dp(c,48));b.setMinimumHeight(dp(c,48));b.setPadding(dp(c,16),dp(c,9),dp(c,16),dp(c,9));b.setElevation(0);android.animation.StateListAnimator motion=new android.animation.StateListAnimator();android.animation.AnimatorSet pressed=new android.animation.AnimatorSet();pressed.playTogether(android.animation.ObjectAnimator.ofFloat(b,"scaleX",.98f),android.animation.ObjectAnimator.ofFloat(b,"scaleY",.98f));pressed.setDuration(100);motion.addState(new int[]{android.R.attr.state_pressed,android.R.attr.state_enabled},pressed);android.animation.AnimatorSet resting=new android.animation.AnimatorSet();resting.playTogether(android.animation.ObjectAnimator.ofFloat(b,"scaleX",1f),android.animation.ObjectAnimator.ofFloat(b,"scaleY",1f));resting.setDuration(250);resting.setInterpolator(new android.view.animation.OvershootInterpolator(.82f));motion.addState(new int[]{},resting);b.setStateListAnimator(motion);String kind=iconFor(b.getText().toString());if(!kind.isEmpty()){b.setText(b.getText().toString().replaceFirst("^[‹›▷▶]\\s*", ""));b.setCompoundDrawables(icon(c,kind,ink),null,null,null);b.setCompoundDrawablePadding(dp(c,7));}b.setMaxWidth(c.getResources().getDisplayMetrics().widthPixels-dp(c,64));}
 static void field(EditText field){Context c=field.getContext();android.graphics.drawable.StateListDrawable states=new android.graphics.drawable.StateListDrawable();GradientDrawable focus=surface(SOFT,16,c);focus.setStroke(dp(c,1),0x88e87c63);states.addState(new int[]{android.R.attr.state_focused},focus);states.addState(new int[]{},surface(SOFT,16,c));field.setBackground(states);field.setTextColor(INK);field.setHintTextColor(0xffa8a199);field.setMinHeight(dp(c,48));field.setPadding(dp(c,14),dp(c,10),dp(c,14),dp(c,10));}
 static void fields(View view){if(view instanceof EditText)field((EditText)view);if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)fields(((ViewGroup)view).getChildAt(i));}
 static void dialog(AlertDialog dialog,boolean sheet){Window window=dialog.getWindow();if(window==null)return;Context c=dialog.getContext();window.setBackgroundDrawable(surface(0xfffffcfa,28,c));window.getDecorView().setClipToOutline(true);window.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams p=window.getAttributes();p.dimAmount=.32f;p.gravity=sheet?Gravity.BOTTOM:Gravity.CENTER;p.width=Math.min(c.getResources().getDisplayMetrics().widthPixels-dp(c,32),dp(c,480));p.height=WindowManager.LayoutParams.WRAP_CONTENT;if(sheet)p.y=dp(c,16);window.setAttributes(p);window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);if(Build.VERSION.SDK_INT>=31){window.setBackgroundBlurRadius(dp(c,12));}TextView message=dialog.findViewById(android.R.id.message);if(message!=null){message.setTextColor(INK);message.setTextSize(14);message.setLineSpacing(dp(c,5),1);message.setPadding(message.getPaddingLeft(),dp(c,8),message.getPaddingRight(),dp(c,14));}
  for(int which:new int[]{DialogInterface.BUTTON_POSITIVE,DialogInterface.BUTTON_NEGATIVE,DialogInterface.BUTTON_NEUTRAL}){Button b=dialog.getButton(which);if(b==null||b.getVisibility()!=View.VISIBLE)continue;control(b,which==DialogInterface.BUTTON_POSITIVE);ViewGroup.LayoutParams existing=b.getLayoutParams();if(existing instanceof LinearLayout.LayoutParams){LinearLayout.LayoutParams lp=(LinearLayout.LayoutParams)existing;lp.leftMargin=dp(c,4);lp.rightMargin=dp(c,4);lp.bottomMargin=dp(c,4);lp.height=ViewGroup.LayoutParams.WRAP_CONTENT;b.setLayoutParams(lp);}if(b.getParent() instanceof ViewGroup){ViewGroup bar=(ViewGroup)b.getParent();bar.setClipChildren(false);bar.setClipToPadding(false);bar.setPadding(bar.getPaddingLeft(),dp(c,10),bar.getPaddingRight(),dp(c,12));bar.setMinimumHeight(dp(c,66));bar.requestLayout();}}
  ListView list=dialog.getListView();if(list!=null){list.setPadding(dp(c,12),dp(c,8),dp(c,12),dp(c,12));list.setDivider(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));list.setDividerHeight(dp(c,5));}
 }
}
